# /etc/nginx/nginx.conf
user www-data;
worker_processes auto;
worker_rlimit_nofile 65535;
pid /run/nginx.pid;
include /etc/nginx/modules-enabled/*.conf;
events { worker_connections 8192; }

http {
    include /etc/nginx/mime.types;
    server_tokens off;
    log_format main '"$request" $status $upstream_addr $upstream_response_time';
    access_log /var/log/nginx/access.log main;

    upstream app {
        zone app 64k;
        server 127.0.0.1:9000 max_fails=3 fail_timeout=10s;
        keepalive 32;
    }

    server {
        listen 80 default_server;
        server_name _;
        location / {
            proxy_pass http://app;
            proxy_http_version 1.1;
            proxy_set_header Connection "";
            proxy_set_header Host $host;
            proxy_connect_timeout 3s;
            proxy_read_timeout 30s;
        }
        location /nginx-health { access_log off; return 200 "ok\n"; }
    }

    server {
        listen 127.0.0.1:8081;
        location /stub_status { stub_status; }
    }
    include /etc/nginx/conf.d/*.conf;
}

include /etc/nginx/stream.d/*.conf;

# /etc/nginx/conf.d/tls.conf
server {
    listen 443 ssl;
    server_name example.test;
    ssl_certificate     /etc/nginx/certs/tls.crt;
    ssl_certificate_key /etc/nginx/certs/tls.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:SSL:10m;
    location / {
        proxy_pass http://app;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
    }
}

# /etc/nginx/conf.d/k8s.conf
upstream k8s_app {
    least_conn;
    server 10.0.20.11:30080 max_fails=3 fail_timeout=10s;   # worker 1 NodePort
    server 10.0.20.12:30080 max_fails=3 fail_timeout=10s;   # worker 2 NodePort
    server 10.0.20.13:30080 max_fails=3 fail_timeout=10s;   # worker 3 NodePort
    keepalive 32;
}
server {
    listen 80;
    server_name app.example.test;
    location / {
        proxy_pass http://k8s_app;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_next_upstream error timeout http_502;
    }
}

sudo tee /etc/nginx/stream.d/pg.conf <<'EOF'
stream {
    upstream pg { server 127.0.0.1:5432; }
    server {
        listen 15432;
        proxy_pass pg;
        proxy_connect_timeout 3s;
        proxy_timeout 1h;
    }
}
EOF
sudo mkdir -p /etc/systemd/system/nginx.service.d
printf '[Service]\nLimitNOFILE=65535\n' | sudo tee /etc/systemd/system/nginx.service.d/limits.conf
sudo nginx -t && sudo systemctl daemon-reload && sudo systemctl enable nginx && sudo systemctl restart nginx
